301→mod tests {
302→    use super::*;
303→    use crate::ui::MockUI;
304→    use tempfile::TempDir;
305→
306→    #[test]
307→    fn init_command_creation() {
308→        let temp = TempDir::new().unwrap();
309→        let args = InitArgs::default();
310→        let cmd = InitCommand::new(temp.path(), args);
311→
312→        assert_eq!(cmd.project_root(), temp.path());
313→        assert!(!cmd.config_exists());
314→    }
315→
316→    #[test]
317→    fn create_config_basic() {
318→        let temp = TempDir::new().unwrap();
319→        let args = InitArgs::default();
320→        let cmd = InitCommand::new(temp.path(), args);
321→
322→        let steps: Vec<(&str, Option<&Template>)> = vec![("bundler", None), ("yarn", None)];
323→        let config = cmd.create_config(&steps);
324→
325→        assert!(config.contains("bundler"));
326→        assert!(config.contains("yarn"));
327→        assert!(config.contains("template: bundler"));
328→        assert!(config.contains("template: yarn"));
329→        assert!(config.contains("workflows:"));
330→        assert!(config.contains("default:"));
331→        assert!(config.contains("steps: [bundler, yarn]"));
332→    }
333→
334→    #[test]
335→    fn create_config_with_templates() {
336→        let temp = TempDir::new().unwrap();
337→        let args = InitArgs::default();
338→        let cmd = InitCommand::new(temp.path(), args);
339→
340→        let loader = BuiltinLoader::new().unwrap();
341→        let bundler = loader.get("bundler");
342→        let yarn = loader.get("yarn");
343→
344→        let steps: Vec<(&str, Option<&Template>)> = vec![("bundler", bundler), ("yarn", yarn)];
345→        let config = cmd.create_config(&steps);
346→
347→        // Should contain template references
348→        assert!(config.contains("template: bundler"));
349→        assert!(config.contains("template: yarn"));
350→
351→        // Should contain commented-out command info from templates
352→        assert!(config.contains("# command: bundle install"));
353→        assert!(config.contains("# command: yarn install"));
354→
355→        // Should contain completed_check comments
356→        assert!(config.contains("# completed_check:"));
357→        assert!(config.contains("#   command: \"bundle check\""));
358→
359→        // Should contain watches
360→        assert!(config.contains("# watches: [Gemfile, Gemfile.lock]"));
