/// Inner loop for the yes/no prompt, separated so the caller can
/// guarantee cursor restoration regardless of how this exits.
fn prompt_yes_no_loop(
    options: &[PromptOption],
    term: &Term,
    sel: &mut usize,
    default_idx: usize,
    pad: &str,
    active_prefix: &Style,
    active_style: &Style,
    inactive_prefix: &Style,
    inactive_style: &Style,
    prompt: &Prompt,
) -> Result<PromptResult> {
    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == *sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
                )
            } else {
                format!(
                    "{}{} {}",
                    pad,
                    inactive_prefix.apply_to("·"),
                    inactive_style.apply_to(&opt.label)
                )
            };
            term.write_line(&line).map_err(BivvyError::Io)?;
        }
        term.flush().map_err(BivvyError::Io)?;

        // Read key — on error (EOF/Ctrl+D), clean up and return default
        let key = match term.read_key() {
            Ok(key) => key,
